const root = $input.first().json;
const body = root.body || root;
const dcr = (((body.data||{}).analysis||{}).data_collection_results) || {};
const g = (k) => { const f = dcr[k]; if(!f) return ''; return (f.value!==undefined? f.value : f) || ''; };
const lob = String(g('line_of_business') || g('insurance_type') || '').toLowerCase();
const map = { car:'MyOrg-CILMConv-Work-LeadCar', auto:'MyOrg-CILMConv-Work-LeadCar', liability:'MyOrg-CILMConv-Work-LeadLiability', home:'MyOrg-CILMConv-Work-LeadHomeContents', home_contents:'MyOrg-CILMConv-Work-LeadHomeContents', legal:'MyOrg-CILMConv-Work-LeadLegal', life:'MyOrg-CILMConv-Work-LeadLife' };
const caseTypeID = map[lob] || 'MyOrg-CILMConv-Work-LeadIntake';
const fullName = g('full_name'); const email = g('email'); const phone = g('mobile_phone')||g('phone'); const postalCode = g('postal_code');
const summary = g('conversation_summary'); const quote = g('indicative_quote');
const label = 'Lead: ' + (fullName||'Unknown') + ' - ' + (lob||'n/a') + (phone? ' - ' + phone : '');
const d = [];
if(email) d.push('Email '+email);
if(postalCode) d.push('PLZ '+postalCode);
if(quote) d.push('Quote '+quote);
if(summary) d.push(summary);
d.push('via Unica voice');
const description = d.join('; ');
return [{ json: { caseTypeID, lineOfBusiness: lob, fullName, email, phone, postalCode, conversationId: ((body.data||{}).conversation_id)||'', label, description } }];
